const d = $input.first().json;
const email = (d.email||'').trim().toLowerCase();
const name = (d.name||'').trim();
const budget = Number(d.budget||0);
const score = (email.includes('@')?40:0) + (budget>=1000?40:budget>0?20:0) + (d.phone?20:0);
const tier = score>=70?'HOT':score>=40?'WARM':'COLD';
return [{ json: { name, email, phone: d.phone||'', company: d.company||'', message: d.message||'', budget, score, tier, received_at: new Date().toISOString() } }];
